/**
 * Grain: a page-wide film-grain layer.
 *
 * The oldest trick in editorial print, and the one thing that stops a flat
 * cream surface reading as a screenshot of a wireframe. Generated by an SVG
 * turbulence filter rather than shipped as a tiling PNG: no download, no
 * seams, and the density is a number in this file rather than a decision
 * baked into an asset.
 *
 * Carries no information, which is why it is aria-hidden. Suppressed under
 * prefers-reduced-motion is unnecessary here, because nothing about it moves —
 * it is texture, not motion, rendered once and never repainted.
 *
 * ── THE DRIFTING COLOUR FIELD THIS FILE USED TO ALSO EXPORT ─────────────────
 *
 * The first restyle of this site put soft blurred shapes of the product
 * colours behind the hero panel and the Continuo bento, exported from here as
 * `Field`. Both of those surfaces are gone in this rebuild — the hero is a
 * plain cream background now, the bento is a plain card grid — and nothing
 * else on the page ever used it, so it went with them rather than staying as
 * a component nothing imports.
 */
export function Grain() {
  return (
    <div
      aria-hidden
      className="pointer-events-none fixed inset-0 z-[60] opacity-[0.055] mix-blend-multiply"
      style={{ contain: "strict" }}
    >
      <svg width="100%" height="100%">
        <filter id="gradlly-grain">
          {/* Fractal noise rather than turbulence: it is finer and reads as
              paper rather than as static. */}
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.82"
            numOctaves="4"
            stitchTiles="stitch"
          />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter="url(#gradlly-grain)" />
      </svg>
    </div>
  );
}
